import sys

def main():
    import sys
    n = int(sys.stdin.readline().strip())
    players = {}

    for _ in range(n):
        name, score = sys.stdin.readline().strip().split()
        score = int(score)

        if name not in players:
            players[name] = 0

        players[name] += score

    max_score = max(players.values())
    winner = None

    for _ in range(n):
        name, score = sys.stdin.readline().strip().split()
        score = int(score)

        if name not  in players:
            players[name] = 0

        players[name] += score

        if players[name] >= max_score:
            winner = name
            break

    print(winner)

if __name__ == "__main__":
    main()
